import { useCallback } from 'react';
import NativeFeedCache from './specs/NativeFeedCache';

type CachedPost = { id: string; seen: boolean };

export function useMarkSeenOnScroll(visibleIds: Set<string>): () => void {
  return useCallback(() => {
    const cached: CachedPost[] = JSON.parse(NativeFeedCache.getAllSync());
    const unseen = cached.filter((p) => visibleIds.has(p.id) && !p.seen);
    if (unseen.length > 0) {
      NativeFeedCache.markSeen(unseen.map((p) => p.id));
    }
  }, [visibleIds]);
}

import { useEffect, useRef, useState } from 'react';
import { Text, View } from 'react-native';

type Props = { label: string; anchorY: number };

export function Tooltip({ label, anchorY }: Props) {
  const ref = useRef<View>(null);
  const [top, setTop] = useState<number>(anchorY);

  useEffect(() => {
    ref.current?.measureInWindow((_x, _y, _width, height) => {
      setTop(anchorY - height - 8);
    });
  }, [anchorY, label]);
  return (
    <View ref={ref} style={{ position: 'absolute', top }}>
      <Text>{label}</Text>
    </View>
  );
}
